CREATE TABLE IF NOT EXISTS pupils(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT UNIQUE NOT NULL,class TEXT,pin_hash TEXT NOT NULL,created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,role TEXT NOT NULL,pupil_id INTEGER,created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS completions(id INTEGER PRIMARY KEY AUTOINCREMENT,pupil_id INTEGER,story TEXT,points INTEGER,perfect INTEGER,reflection TEXT,ts TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS runs(id INTEGER PRIMARY KEY AUTOINCREMENT,pupil_id INTEGER,story TEXT,state TEXT,done INTEGER DEFAULT 0,ts TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS picks(id INTEGER PRIMARY KEY AUTOINCREMENT,pupil_id INTEGER,run INTEGER,story TEXT,node TEXT,idx INTEGER,r TEXT,p INTEGER,bt TEXT,tries INTEGER,ms INTEGER,ts TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS writings(id INTEGER PRIMARY KEY AUTOINCREMENT,pupil_id INTEGER,story TEXT,text TEXT,checks TEXT,comment TEXT,ts TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sorts(id INTEGER PRIMARY KEY AUTOINCREMENT,pupil_id INTEGER,score INTEGER,total INTEGER,ts TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS assignments(class TEXT,story TEXT,PRIMARY KEY(class,story));
CREATE TABLE IF NOT EXISTS fails(k TEXT PRIMARY KEY,n INTEGER,ts INTEGER);
CREATE INDEX IF NOT EXISTS i_picks ON picks(pupil_id,story);
CREATE TABLE IF NOT EXISTS teachers(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT UNIQUE NOT NULL,salt TEXT NOT NULL,hash TEXT NOT NULL,created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS teacher_classes(teacher_id INTEGER,class TEXT,PRIMARY KEY(teacher_id,class));
CREATE TABLE IF NOT EXISTS skill_log(id INTEGER PRIMARY KEY AUTOINCREMENT,pupil_id INTEGER,skill TEXT,ok INTEGER,ts TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS i_skill ON skill_log(pupil_id,skill);
CREATE TABLE IF NOT EXISTS xp_log(id INTEGER PRIMARY KEY AUTOINCREMENT,pupil_id INTEGER,kind TEXT,xp INTEGER,ref TEXT,ts TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS i_xp ON xp_log(pupil_id);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT);
CREATE TABLE IF NOT EXISTS ai_checks(id INTEGER PRIMARY KEY AUTOINCREMENT,pupil_id INTEGER,run INTEGER,story TEXT,rule TEXT,text_hash TEXT,snippet TEXT,verdicts TEXT,outcome TEXT,reason TEXT,source TEXT,reattempts INTEGER DEFAULT 0,writing_id INTEGER,ts TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS i_aic ON ai_checks(run,rule);
CREATE TABLE IF NOT EXISTS transfer_log(id INTEGER PRIMARY KEY AUTOINCREMENT,pupil_id INTEGER,kind TEXT,task TEXT,a INTEGER,b INTEGER,c INTEGER,wrong TEXT DEFAULT '',ts TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS i_tr ON transfer_log(pupil_id,kind,task);
